// KR5 (review 2026-11-15, finding 31): counts in README.md and the WORLD.md files are generated by tools/counts.mjs
// between `<!--n:SPEC-->` markers; the ten stale counts the review listed are markers now.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { REPO, scanWorlds } from '../tools/lib/worlds.mjs';
import { countedFiles, counter } from '../tools/counts.mjs';

const worlds = scanWorlds();

test('every marked count is what tools/counts.mjs gives (npm run build rewrites them)', () => {
  const files = countedFiles(worlds);
  assert.ok(Object.keys(files).length >= 6);
  for (const [f, text] of Object.entries(files)) assert.equal(readFileSync(join(REPO, f), 'utf8'), text, `${f}: run node tools/counts.mjs`);
});

test('the counts the review found stale are generated: worlds, objects, roles, acts, verbs, markings, animals, shapes, foods, k.named, drawing slots', () => {
  const where = { 'README.md': ['worlds', 'schemas', 'facts:k.objects.object', 'facts:k.people.role', 'facts:k.actions.act', 'facts:k.actions.verb', 'facts:k.animals.animal'],
    'docs/worlds/k.people/WORLD.md': ['facts:k.people.role'], 'docs/worlds/k.shapes/WORLD.md': ['facts:k.shapes.shape'], 'docs/worlds/k.food/WORLD.md': ['facts:k.food.food'],
    'docs/worlds/k.actions/WORLD.md': ['facts:k.actions.verb', 'facts:k.actions.marking'], 'docs/worlds/README.md': ['named-takers', 'slots:drawing', 'slot-worlds:drawing'] };
  for (const [f, specs] of Object.entries(where)) { const text = readFileSync(join(REPO, f), 'utf8'); for (const s of specs) assert.ok(text.includes(`<!--n:${s}-->`), `${f}: ${s}`); }
  const n = counter(worlds);
  assert.equal(n('worlds'), worlds.length);
  assert.ok(n('facts:k.objects.object') > 2000 && n('facts:k.actions.act') >= 16);
  assert.throws(() => n('nonsense'), /unknown spec/);
});
